vec3 dy = ( GetBlur1(uv+vec2( 0.0 , 1.0 )*d)-GetBlur1(uv-vec2( 0.0 , 1.0 )*d).xy );
vec2 uv_y = uv-vec2(dx.y,dy.y)*0.4;
vec2 uv_dx = uv - vec2(dx.x,dy.x) * 1.0;
vec2 uv_dz = uv - vec2(dx.z,dy.z) * 1.0;
ret = 0;
ret = mix(ret, vec3(0.8,0.4,1.5)*_qb, length(vec2(dx.x,dy.x)));
ret = mix(ret,vec3( 1.0 , 1.0 , 0.0)*_qb.zxy,GetPixel(uv).x*clamp01(1.0 - GetBlur3(uv).y * 8.0));
ret = mix(ret, 1.0 ,GetBlur1(uv_dx).z*GetBlur1(uv).x * 2.0*(1.0 - GetBlur1(uv).y * 4.0));
ret = mix(ret, vec3( 0.0 , 1.0 , 0.0)*_qb.yzx, length(vec2(dx.z,dy.z)));
ret = mix(ret,vec3( 1.0 , 0.0 , 0.0)*_qb.yzx,GetPixel(uv).z*clamp01(1.0 - GetBlur3(uv).y * 8.0));
ret = mix(ret, 1.0 ,GetBlur1(uv_dz).x*GetBlur1(uv).z * 2.0*(1.0 - GetBlur1(uv).y * 4.0));
ret = mix(clamp01(ret),_qb,GetPixel(uv).y);
}

